const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const KEY='spool-inventory-v1';
const seed=[['PLA Basic','Bambu Lab','PLA','ジェイドホワイト','#e5e8db',850,'ドライボックス A'],['PLA Basic','Bambu Lab','PLA','マットブラック','#343a38',1000,'ドライボックス A'],['PLA Translucent','Bambu Lab','PLA','アイスブルー','#a7cbe2',600,'ドライボックス B'],['PLA Matte','Bambu Lab','PLA','ラテブラウン','#b8a28a',180,'ドライボックス A'],['PETG HF','Bambu Lab','PETG','フォレストグリーン','#47796a',720,'ドライボックス B'],['PLA Silk','eSUN','PLA','シャンパンゴールド','#c7ae73',995,'シェルフ 01'],['PolyLite ABS','Polymaker','ABS','パステルピンク','#dfaaa5',120,'シェルフ 02'],['TPU 95A','SUNLU','TPU','ナチュラルホワイト','#e7e5de',0,'シェルフ 02']].map((a,i)=>({id:'sample-'+i,name:a[0],brand:a[1],material:a[2],colorName:a[3],color:a[4],remaining:a[5],capacity:1000,location:a[6],diameter:'1.75',note:'サンプル在庫です。実際の在庫に合わせて編集してください。',image:'',sample:true}));
const selected=new Set();let visibleIds=[],bulkIds=[],bulkMode='add';const TRASH_KEY=KEY+'-deleted';let deleted=[];try{const trash=JSON.parse(localStorage.getItem(TRASH_KEY)||'[]');if(Array.isArray(trash)&&trash.every(valid))deleted=trash}catch{}
let items,tab='all',view='list',editId=null,photo='',usageId=null;
try{items=JSON.parse(localStorage.getItem(KEY))||structuredClone(seed)}catch{items=structuredClone(seed)}
function safeUrl(value){if(!value||typeof value!=='string')return '';try{const url=new URL(value);return ['https:','http:'].includes(url.protocol)&&!url.username&&!url.password?url.href:''}catch{return ''}}
function valid(x){return x&&typeof x.id==='string'&&typeof x.name==='string'&&x.name.trim()&&typeof x.brand==='string'&&typeof x.material==='string'&&typeof x.colorName==='string'&&/^#[0-9a-f]{6}$/i.test(x.color)&&Number.isFinite(x.remaining)&&Number.isFinite(x.capacity)&&x.remaining>=0&&x.capacity>0&&x.remaining<=x.capacity&&x.capacity<=100000&&(!x.image||/^data:image\/(png|jpeg|webp);base64,/.test(x.image))}
if(!Array.isArray(items)||!items.every(valid))items=structuredClone(seed);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function spool(color){const svg=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 220 180"><defs><linearGradient id="r"><stop stop-color="#c8cec8"/><stop offset=".4" stop-color="#f0f0e8"/><stop offset="1" stop-color="#afb7ad"/></linearGradient><linearGradient id="f"><stop stop-color="${color}"/><stop offset=".45" stop-color="${color}"/><stop offset="1" stop-color="#000" stop-opacity=".45"/></linearGradient><pattern id="lines" width="3" height="3" patternUnits="userSpaceOnUse"><path d="M0 0V3" stroke="#fff" opacity=".19"/></pattern><filter id="s"><feGaussianBlur stdDeviation="5"/></filter></defs><ellipse cx="112" cy="155" rx="65" ry="9" fill="#32422b" opacity=".12" filter="url(#s)"/><g transform="rotate(-13 110 90)"><ellipse cx="83" cy="85" rx="43" ry="64" fill="#b5bcb1"/><rect x="83" y="28" width="61" height="115" fill="url(#f)"/><rect x="83" y="28" width="61" height="115" fill="url(#lines)"/><ellipse cx="146" cy="85" rx="43" ry="64" fill="url(#r)"/><ellipse cx="146" cy="85" rx="35" ry="54" fill="#dce1d5" stroke="#b8c0b2"/><ellipse cx="146" cy="85" rx="27" ry="44" fill="${color}"/><ellipse cx="146" cy="85" rx="22" ry="37" fill="none" stroke="#fff" opacity=".14" stroke-width="9"/><ellipse cx="146" cy="85" rx="15" ry="24" fill="#d7ddcf"/><ellipse cx="146" cy="85" rx="9" ry="15" fill="#566050"/><ellipse cx="149" cy="83" rx="5" ry="12" fill="#333b30"/><path d="M129 44l9 11M165 119l-8-11M121 107l13-5M172 66l-12 4" stroke="#f7f7ef" stroke-width="8" stroke-linecap="round"/></g></svg>`;return 'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg)}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function save(next){try{localStorage.setItem(KEY,JSON.stringify(next));items=next;render();return true}catch{toast('保存容量が不足しています。画像を減らすかバックアップしてください。');return false}}
function options(id,key,title){const el=$(id),v=el.value;el.innerHTML='<option value="">'+title+'</option>'+[...new Set(items.map(x=>x[key]))].sort().map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');el.value=v}
function render(){const active=items.filter(x=>x.remaining>0),low=items.filter(x=>x.remaining>0&&x.remaining<=200),materials=[...new Set(active.map(x=>x.material))];$('#statCount').textContent=active.length;$('#navCount').textContent=items.length;$('#lowCount').textContent=low.length;$('#statWeight').textContent=(items.reduce((a,x)=>a+x.remaining,0)/1000).toFixed(2);$('#statMaterials').textContent=materials.length;$('#materialNames').textContent=materials.join(' / ');$('#statLow').textContent=low.length;$('#totalCount').textContent=items.length;options('#brand','brand','すべてのブランド');options('#material','material','すべての素材');
 const q=$('#search').value.trim().toLowerCase();let shown=items.filter(x=>(tab==='all'||(tab==='low'?x.remaining>0&&x.remaining<=200:x.remaining===0))&&(!$('#brand').value||x.brand===$('#brand').value)&&(!$('#material').value||x.material===$('#material').value)&&[x.name,x.brand,x.colorName,x.location,x.material].join(' ').toLowerCase().includes(q));if($('#sort').value==='remaining')shown.sort((a,b)=>a.remaining-b.remaining);if($('#sort').value==='name')shown.sort((a,b)=>a.name.localeCompare(b.name,'ja'));
 visibleIds=shown.map(x=>x.id);for(const id of selected)if(!visibleIds.includes(id))selected.delete(id);
 $('#items').className=view==='grid'?'grid-mode':'';$('.table-label').style.display=view==='grid'?'none':'';$('#items').innerHTML=shown.length?shown.map(x=>{const pct=Math.round(x.remaining/x.capacity*100);return `<article class="filament-row ${!x.remaining?'empty':x.remaining<=200?'low':''}"><input class="row-select" type="checkbox" data-select="${esc(x.id)}" aria-label="${esc(x.name)} ${esc(x.colorName)}を選択" ${selected.has(x.id)?"checked":""}><button class="product" data-edit="${esc(x.id)}" title="詳細・編集"><img class="product-image" src="${esc(x.image||spool(x.color))}" alt="${esc(x.name)} ${x.image?'商品画像':'スプールイラスト'}"><div><span class="brand-name">${esc(x.brand)}${x.sample?' · SAMPLE':''}</span><h3>${esc(x.name)}</h3><span class="color-name"><i class="color-chip" style="background:${x.color}"></i>${esc(x.colorName)}</span></div></button><div class="material"><span class="material-badge">${esc(x.material)}</span><span class="diameter">${esc(x.diameter)} mm</span></div><div class="weight"><div class="weight-top"><span class="weight-number">${x.remaining.toLocaleString()} <small>/ ${x.capacity.toLocaleString()} g</small></span><span class="percent">${pct}%</span></div><div class="bar"><i style="width:${pct}%"></i></div></div><div class="place">▱ ${esc(x.location||'未設定')}</div><div class="actions">${safeUrl(x.amazonUrl)?`<a class="shop-link" href="${esc(safeUrl(x.amazonUrl))}" target="_blank" rel="noopener noreferrer" title="Amazonの販売ページを開く" aria-label="${esc(x.name)}のAmazon販売ページを開く">Amazon ↗</a>`:""}${safeUrl(x.shopUrl)?`<a class="shop-link" href="${esc(safeUrl(x.shopUrl))}" target="_blank" rel="noopener noreferrer" title="公式サイト・販売ページを開く" aria-label="${esc(x.name)}の公式サイト・販売ページを開く">販売元 ↗</a>`:""}<button data-use="${esc(x.id)}" aria-label="${esc(x.name)}の使用量を記録" title="使用量を記録">−</button><button data-edit="${esc(x.id)}" aria-label="${esc(x.name)}を編集" title="編集">⋯</button></div></article>`}).join(''):'<div class="empty-state">該当するフィラメントがありません。<br><br>絞り込み条件を変えるか、新しいフィラメントを追加してください。</div>';$('#shown').textContent=`${items.length} スプール中 ${shown.length} 件を表示`;$$('[data-edit]').forEach(b=>b.onclick=()=>openEditor(b.dataset.edit));$('[data-use]').forEach(b=>b.onclick=()=>openUsage(b.dataset.use));$('[data-select]').forEach(b=>b.onchange=()=>{b.checked?selected.add(b.dataset.select):selected.delete(b.dataset.select);updateSelection()});updateSelection();}
function setTab(t){tab=t;$$('[data-tab]').forEach(b=>b.classList.toggle('selected',b.dataset.tab===t));$$('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===t));render()}
$$('[data-tab]').forEach(b=>b.onclick=()=>setTab(b.dataset.tab));$$('[data-nav]').forEach(b=>b.onclick=()=>setTab(b.dataset.nav));['#search','#brand','#material','#sort'].forEach(id=>$(id).addEventListener(id==='#search'?'input':'change',render));$('#listView').onclick=()=>changeView('list');$('#gridView').onclick=()=>changeView('grid');function changeView(v){view=v;$('#listView').classList.toggle('selected',v==='list');$('#gridView').classList.toggle('selected',v==='grid');render()}
function openEditor(id){editId=id||null;$('#form').reset();$('#formError').textContent='';$('#photo').value='';$('#imageStatus').textContent='画像エリアをクリックしてから Ctrl+V で貼り付けできます。';const item=items.find(x=>x.id===id);if(item)for(const [key,value]of Object.entries(item)){const field=$('#form').elements.namedItem(key);if(field)field.value=value}photo=item?.image||'';$('#dialogTitle').textContent=item?'フィラメントを編集':'フィラメントを追加';$('#delete').hidden=!item;$('#copiesField').hidden=!!item;$('#form').elements.namedItem('copies').disabled=!!item;updatePreview();$('#editor').showModal()}
function updatePreview(){$('#imagePreview').src=photo||spool($('#form').elements.namedItem('color').value)}$('#form').elements.namedItem('color').oninput=updatePreview;$('#clearPhoto').onclick=()=>{imageJob++;photo='';$('#photo').value='';updatePreview();$('#imageStatus').textContent='画像を解除しました。「保存する」で反映されます。'};$('#add').onclick=()=>openEditor();$('#closeEditor').onclick=$('#cancel').onclick=()=>$('#editor').close();
let imageJob=0;
async function attachImage(file){const job=++imageJob;if(file.size>5*1024*1024){toast('5MB以下の画像を選んでください');return}try{const bitmap=await createImageBitmap(file);const canvas=document.createElement('canvas');const ratio=Math.min(1,700/Math.max(bitmap.width,bitmap.height));canvas.width=Math.max(1,Math.round(bitmap.width*ratio));canvas.height=Math.max(1,Math.round(bitmap.height*ratio));const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();if(job!==imageJob||!$('#editor').open)return;photo=canvas.toDataURL('image/jpeg',.83);updatePreview();$('#imageStatus').textContent='画像を取り込みました。「保存する」で登録してください。';toast('画像を取り込みました')}catch{toast('画像を読み込めませんでした。画像ファイルを選択してください')}}
$('#photo').onchange=e=>{const file=e.target.files[0];if(file)attachImage(file)};
$('#editor').addEventListener('paste',e=>{const entry=[...(e.clipboardData?.items||[])].find(x=>x.type.startsWith('image/'));if(!entry)return;const file=entry.getAsFile();if(file){e.preventDefault();attachImage(file)}});
const drop=$('#imageDrop');drop.addEventListener('dragover',e=>{e.preventDefault();drop.classList.add('drag-over')});drop.addEventListener('dragleave',()=>drop.classList.remove('drag-over'));drop.addEventListener('drop',e=>{e.preventDefault();drop.classList.remove('drag-over');const file=[...e.dataTransfer.files].find(f=>f.type.startsWith('image/'));if(file)attachImage(file);else toast('画像ファイルをドロップしてください')});
$('#editor').addEventListener('close',()=>{imageJob++});
$('#form').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));data.remaining=Number(data.remaining);data.capacity=Number(data.capacity);data.id=editId||crypto.randomUUID();data.image=photo;data.name=data.name.trim();data.brand=data.brand.trim();data.colorName=data.colorName.trim();for(const key of ['amazonUrl','shopUrl']){const value=data[key].trim();if(value&&!safeUrl(value)){$('#formError').textContent='販売ページは https:// または http:// で始まるURLを入力してください。';return}data[key]=safeUrl(value)}if(!valid(data)){$('#formError').textContent='名前・ブランド・カラーを入力し、残量を初期重量以下にしてください。';return}const copies=Number(data.copies||1);delete data.copies;if(!Number.isInteger(copies)||copies<1||copies>100){$('#formError').textContent='追加本数は1〜100本で指定してください。';return}const next=editId?items.map(x=>x.id===editId?data:x):[...makeCopies([data],copies,false),...items];if(save(next)){$('#editor').close();toast('フィラメントを保存しました')}};
$('#delete').onclick=()=>{const x=items.find(x=>x.id===editId);if(confirm(`「${x.name} / ${x.colorName}」を削除しますか？`)&&save(items.filter(x=>x.id!==editId))){$('#editor').close();toast('フィラメントを削除しました')}};
function openUsage(id){const x=items.find(x=>x.id===id);if(!x.remaining){toast('このスプールは使い切っています');return}usageId=id;$('#usageName').textContent=`${x.name} · ${x.colorName} / 残り ${x.remaining} g`;$('#used').value='';$('#used').max=x.remaining;$('#usageError').textContent='';$('#usage').showModal()}$('#closeUsage').onclick=()=>$('#usage').close();$('#usageForm').onsubmit=e=>{e.preventDefault();const x=items.find(x=>x.id===usageId),n=Number($('#used').value);if(n<=0||n>x.remaining){$('#usageError').textContent='現在の残量以下の使用量を入力してください。';return}if(save(items.map(x=>x.id===usageId?{...x,remaining:x.remaining-n}:x))){$('#usage').close();toast(`${n} g の使用を記録しました`)}};
$('#export').onclick=()=>{const blob=new Blob([JSON.stringify({version:1,exportedAt:new Date().toISOString(),items},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='spool-backup-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('バックアップを出力しました')};$('#import').onclick=()=>$('#importFile').click();$('#importFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>15000000)throw Error();const data=JSON.parse(await f.text());if(data.version!==1||!Array.isArray(data.items)||!data.items.every(valid)||new Set(data.items.map(x=>x.id)).size!==data.items.length)throw Error();if(confirm(`${data.items.length} 件のバックアップで現在の在庫を置き換えます。続けますか？`)&&save(data.items))toast('バックアップを読み込みました')}catch{toast('有効なSPOOLバックアップを選んでください')}e.target.value=''};

function makeCopies(source,count,full){return source.flatMap(x=>Array.from({length:count},()=>({...x,id:crypto.randomUUID(),sample:false,remaining:full?x.capacity:x.remaining})))}
function updateSelection(){const count=selected.size;$('#selectionCount').textContent=count+' 件選択';$('#selectAll').checked=visibleIds.length>0&&count===visibleIds.length;$('#selectAll').indeterminate=count>0&&count<visibleIds.length;$('#selectAll').disabled=!visibleIds.length;for(const id of ['#clearSelection','#bulkAdd','#bulkDelete'])$(id).disabled=!count;$$('[data-select]').forEach(el=>{el.checked=selected.has(el.dataset.select);el.closest('.filament-row').classList.toggle('is-selected',el.checked)});const rest=deleted.filter(x=>!items.some(i=>i.id===x.id));$('#undoBar').hidden=!rest.length;$('#undoText').textContent=rest.length+' 件を削除しました。';}
$('#selectAll').onchange=e=>{selected.clear();if(e.target.checked)visibleIds.forEach(id=>selected.add(id));updateSelection()};$('#clearSelection').onclick=()=>{selected.clear();updateSelection()};
function openBulk(mode){bulkMode=mode;bulkIds=[...selected];if(!bulkIds.length)return;$('#bulkTitle').textContent=mode==='add'?'選択したフィラメントを一括追加':'選択したフィラメントを一括削除';$('#bulkDescription').textContent=mode==='add'?'画像・カラー・販売ページなどを引き継いで、新しいスプールを追加します。':'次のフィラメントを削除します。削除後は一覧の「削除を元に戻す」で復元できます。';$('#bulkPreview').innerHTML=items.filter(x=>bulkIds.includes(x.id)).map(x=>'<li>'+esc(x.brand+' / '+x.name+' / '+x.colorName)+'</li>').join('');$('#bulkAddFields').hidden=mode!=='add';$('#bulkCopies').disabled=mode!=='add';$('#bulkCopies').value=1;$('#resetRemaining').checked=true;$('#bulkError').textContent='';$('#confirmBulk').textContent=mode==='add'?'追加する':'削除する';$('#confirmBulk').classList.toggle('delete-confirm',mode==='delete');updateBulkSummary();$('#bulkDialog').showModal()}
function updateBulkSummary(){const n=Number($('#bulkCopies').value);$('#bulkSummary').textContent=bulkMode==='add'?bulkIds.length+' 商品 × '+(Number.isInteger(n)&&n>0?n:'—')+' 本 ＝ '+(Number.isInteger(n)&&n>0?bulkIds.length*n:'—')+' 本を追加':bulkIds.length+' 件を削除';}
$('#bulkCopies').oninput=updateBulkSummary;$('#bulkAdd').onclick=()=>openBulk('add');$('#bulkDelete').onclick=()=>openBulk('delete');$('#closeBulk').onclick=$('#cancelBulk').onclick=()=>$('#bulkDialog').close();
$('#bulkForm').onsubmit=e=>{e.preventDefault();const source=items.filter(x=>bulkIds.includes(x.id));if(!source.length){$('#bulkDialog').close();return}if(bulkMode==='add'){const count=Number($('#bulkCopies').value);if(!Number.isInteger(count)||count<1||count>100||source.length*count>500){$('#bulkError').textContent='各商品1〜100本、合計500本以内で指定してください。';return}if(save([...makeCopies(source,count,$('#resetRemaining').checked),...items])){selected.clear();updateSelection();$('#bulkDialog').close();toast(source.length*count+' 本を追加しました')}}else{try{localStorage.setItem(TRASH_KEY,JSON.stringify(source))}catch{$('#bulkError').textContent='復元用データを保存できません。バックアップや画像容量をご確認ください。';return}deleted=source;if(save(items.filter(x=>!bulkIds.includes(x.id)))){selected.clear();updateSelection();$('#bulkDialog').close();toast(source.length+' 件を削除しました')}}};
$('#undoDelete').onclick=()=>{const restored=deleted.filter(x=>!items.some(i=>i.id===x.id));if(restored.length&&save([...restored,...items])){deleted=[];try{localStorage.removeItem(TRASH_KEY)}catch{}updateSelection();toast(restored.length+' 件を復元しました')}};
render();
